"描述定制嗓音:免选音色——角色配音按项目声纹卡(voice.json 声学字段)自动拼装声线描述,旁白按项目旁白声线卡冻结描述(无卡按工单 --instructions);项目已有冻结 voiceprint 样本时自动作参考锚,同一角色逐句/逐段合成不漂音色。": "Voz personalizada por descrição: sem escolher voz — a dublagem de personagens monta automaticamente a descrição a partir do cartão de impressão vocal do projeto (campos acústicos do voice.json); a narração usa a descrição congelada do cartão de voz do narrador (sem cartão: --instructions da ordem); se já houver amostra voiceprint congelada, ela vira âncora de referência automaticamente e a voz não deriva na síntese por frase/segmento.",
