"Agent 高级设置": "Configurações avançadas de Agent",
"Agent 高级设置:扇出型 Agent 并发额度、运行/无输出超时、跨轮对话记忆额度、自动重跑次数上限、重跑等待确认时间、思考深度": "Configurações avançadas de agentes: concorrência de agentes fan-out, tempos limite de execução / sem saída, cota de memória de conversa entre turnos, teto de repetições automáticas, tempo de espera da confirmação de repetição, profundidade de raciocínio",
"重跑等待确认(秒)": "Espera de confirmação de repetição (s)",
"重跑等待确认需为 {min}-{max} 的整数(秒)": "A espera de confirmação de repetição deve ser um inteiro entre {min} e {max} (segundos)",
"重跑类确认弹窗(「是否重跑?」等)的等待时长,默认 60 秒:倒计时结束无人答复即自动采用默认选项(通常为「重跑」),流水线不会因等人而卡住。调大可给自己留更多裁决时间,代价是无人值守时流水线在弹窗上等得更久;Agent 显式指定的更短等待仍有效,但不能超过本值。签字类弹窗(H 门人工签字)永不倒计时、永不自动确认,不受本项影响。全局设置,保存后对后续发起的确认生效。": "Tempo de espera dos avisos de confirmação do tipo repetição («Repetir?», etc.), padrão de 60 segundos: se a contagem regressiva terminar sem resposta, a opção padrão (normalmente «Repetir») é aplicada automaticamente, de modo que o pipeline nunca fica travado esperando alguém. Aumentar dá mais tempo para decidir, ao custo de o pipeline esperar mais no aviso quando ninguém está por perto; uma espera mais curta pedida explicitamente por um agente continua valendo, mas nunca pode exceder este valor. Avisos de assinatura (assinatura manual dos portões H) nunca têm contagem regressiva nem se confirmam sozinhos, portanto não são afetados. Configuração global; vale para confirmações emitidas após salvar.",
"⚙️ Agent 高级设置": "⚙️ Configurações avançadas de Agent",
"重跑次数": "Repetições",
"Agent 自动重跑/重 roll 的次数上限,默认 0:验收评分、QA 审核或机检不过时,总制片带意见自动退回重做;视频/图像生成机检不达标时自动重 roll。同一任务累计达到该次数仍不过就升级用户裁决,不再自行重试;填 0 则完全不自动重跑,首次不过即升级人工。全局设置,通过运行提示词注入所有 Agent,覆盖流程文档里写死的「最多 3 次」,保存后对后续启动的工单生效。": "Teto de reexecuções / re-rolls automáticos dos agentes, padrão 0: se a pontuação de aceitação, a revisão de QA ou a verificação automática falharem, o Produtor devolve o trabalho com comentários para refazer; se a geração de vídeo/imagem falhar na verificação automática, ela é re-rolada automaticamente. Quando a mesma tarefa atinge esse número e ainda falha, é escalada ao usuário em vez de tentar de novo; 0 desativa totalmente a repetição automática (a primeira falha é escalada). Configuração global, injetada em todos os agentes pelo prompt de execução e que sobrepõe o «no máximo 3 vezes» fixado na documentação; vale para execuções iniciadas após salvar.",
"重跑次数需为 0-{max} 的整数(0=不自动重跑)": "O número de repetições deve ser um inteiro entre 0 e {max} (0 = sem repetição automática)",
"轮次上限": "Limite de turnos",
"单个工单内引擎的对话轮次上限,默认 250:仅对 claude 与 grok 引擎生效(headless 的 --max-turns 参数,不传则不限,这里主动设闸防失控循环);codex/pi/opencode 引擎无此参数不受影响,deepagents 走框架自身的递归上限。撞上限时引擎会被直接切断且无法续跑,回执只显示退出码 1,已落盘的产物保留但核验与回执缺失——大批量工位(逐组选片、批量切片)一单几十组时 100 轮远远不够,如仍撞限优先调小派单批宽、其次上调本值。全局设置,保存后对后续启动的工单生效。": "Teto de turnos de conversa do motor por ordem de trabalho, padrão 250: afeta apenas os motores claude e grok (parâmetro headless --max-turns; omiti-lo significa ilimitado — esta trava evita loops descontrolados). Os motores codex/pi/opencode não têm esse parâmetro e não são afetados; o deepagents usa o limite de recursão do próprio framework. Ao atingir o teto, o motor é cortado sem possibilidade de retomar — o recibo mostra apenas o código de saída 1; artefatos já gravados permanecem, mas a verificação e o recibo ficam faltando. Em estações de alto volume (curadoria por grupo, corte em lote), uma ordem com dezenas de grupos torna 100 turnos muito poucos; se ainda atingir o teto, reduza primeiro o tamanho do lote e depois aumente este valor. Configuração global; vale para execuções iniciadas após salvar.",
"轮次上限需为 {min}-{max} 的整数": "O limite de turnos deve ser um inteiro entre {min} e {max}",
"思考深度": "Profundidade de raciocínio",
"引擎默认": "Padrão do motor",
"思考深度(Thinking Effort)统一设置,默认「引擎默认」:派单时按当前引擎翻译成各自的推理强度参数——claude → --effort,codex → model_reasoning_effort(无 max,按 xhigh),pi → --thinking,opencode → --variant(模型没有该档位时被忽略),grok → --reasoning-effort(无 max,按 xhigh),deepagents → reasoning_effort(仅云端/OpenRouter 渠道,本地模型不传);kimi CLI 无对应参数,不受影响。越深越稳但越慢、token 消耗越高;「引擎默认」不传任何参数,沿用各引擎自身配置(如 ~/.claude/settings.json 的 effortLevel、~/.codex/config.toml 的 model_reasoning_effort)。全局设置,对所有 Agent 生效,保存后对后续启动的工单生效。": "Configuração unificada de profundidade de raciocínio (Thinking Effort), padrão «Padrão do motor»: no despacho é traduzida no parâmetro de intensidade de raciocínio de cada motor — claude → --effort, codex → model_reasoning_effort (sem max; usa xhigh), pi → --thinking, opencode → --variant (ignorado se o modelo não tiver esse nível), grok → --reasoning-effort (sem max; mapeado para xhigh), deepagents → reasoning_effort (apenas canais nuvem/OpenRouter; não enviado a modelos locais); a CLI do kimi não tem parâmetro equivalente e não é afetada. Mais profundo é mais estável, porém mais lento e consome mais tokens; «Padrão do motor» não passa nada e mantém a configuração própria de cada motor (ex. effortLevel em ~/.claude/settings.json, model_reasoning_effort em ~/.codex/config.toml). Configuração global para todos os agentes, válida para execuções iniciadas após salvar.",
