"Seedance 2.5(最新,单段30秒直出,参考上限30图+10视频+10音频,480p/720p)": "Seedance 2.5 (mais recente, vídeo de 30 segundos numa única geração, até 30 imagens + 10 vídeos + 10 áudios de referência, 480p/720p)",
"Seedance 2.0(音画同生,多模态生视频,最高4K)": "Seedance 2.0 (áudio e vídeo simultâneos, geração multimodal de vídeo, até 4K)",
"对话记忆": "Memória conversacional",
"对话记忆额度(KB,默认 16):创作型 Agent 每次运行接续上次会话,多轮对话有连续记忆;单个会话历史超过该额度自动新开会话防膨胀(扇出型无状态 Agent 本就每单全新会话,不受此项影响)。调大可保留更长的连续记忆,但 resume 每轮重发全部历史,越大越慢、token 消耗越高。拖到 0 即完全关闭:所有 Agent(含总制片)每次运行/发言都是全新会话,跨工单信息只靠落盘产物(bible、工单档案等)传递,可显著省 token,但对话上下文不再延续。全局设置,保存后立即对后续运行生效;调小或关闭期间会话号照常回存,重新调大后从最近一次会话继续。": "Cota de memória de conversa (KB, padrão 16): os Agents criativos retomam a sessão anterior a cada execução, mantendo memória contínua nas conversas de vários turnos; se o histórico de uma sessão passar dessa cota, uma nova sessão é aberta automaticamente para evitar inchaço (Agents fan-out sem estado já iniciam uma sessão nova por ticket e não são afetados). Uma cota maior preserva memória contínua mais longa, mas o resume reenvia todo o histórico a cada turno — quanto maior, mais lento e mais tokens consome. Arraste até 0 para desligar por completo: todos os Agents — incluindo o Produtor — iniciam uma sessão nova a cada execução/mensagem, e as informações entre tickets só passam pelos artefatos em disco (bible, registros de tickets etc.), o que economiza muitos tokens mas perde a continuidade da conversa. Configuração global; vale imediatamente para as próximas execuções. Com a cota reduzida ou em 0, os IDs de sessão continuam sendo salvos: ao aumentá-la de novo, retoma-se da sessão mais recente.",
"✓ 会话恢复生效中:单会话超过 {kb} KB 自动新开": "✓ Retomada de sessão ativa: uma sessão acima de {kb} KB reinicia automaticamente",
"对话记忆需为 0-{max} 的整数(KB,0=关闭)": "A memória de conversa deve ser um inteiro entre 0 e {max} (KB, 0 = desligada)",
"已关闭:每次运行全新会话": "Desligada: cada execução inicia sessão nova",
"跨 Agent 并发额度": "Cota de concorrência entre Agents",
"全局同时运行的工单(工人进程)总上限,默认 8,最高 50:所有 Agent 的运行共用这一池进程槽,占满后新工单排队等槽;总制片等调度型 Agent 大部分时间静默等子任务,不占槽。它同时是下方「单 Agent 并发额度」的取值上限。每个槽 = 一个真实的模型 CLI 进程,调大会同步放大 token 消耗速度、本机负载与网络代理并发压力,建议按机器与额度承受力逐步上调。保存后立即对后续启动的工单生效。": "Teto global de tickets (processos de trabalho) em execução simultânea; padrão 8, máximo 50. As execuções de todos os Agents compartilham este único pool de slots de processo; quando lota, novos tickets aguardam um slot. Agents coordenadores, como o produtor-geral, passam a maior parte do tempo aguardando subtarefas e não ocupam slot. É também o limite superior da «Cota de concorrência por Agent» abaixo. Cada slot = um processo CLI real do modelo — aumentar o valor amplia ao mesmo tempo o ritmo de consumo de tokens, a carga local e a pressão de concorrência no proxy; aumente gradualmente conforme a máquina e a cota suportarem. Vale para execuções iniciadas após salvar.",
"跨 Agent 并发额度需为 1-{max} 的整数": "A cota de concorrência entre Agents deve ser um inteiro entre 1 e {max}",
"单 Agent 并发额度": "Cota de concorrência por Agent",
"扇出型 Agent(场景资产、视频生成、审核、验收评分等按场景/组一单的工位)同一 Agent 可同时运行的工单数上限,默认 5,最大不超过上方「跨 Agent 并发额度」。创作型 Agent 为保护会话连续性恒为串行,不受此值影响;全部运行仍受跨 Agent 并发额度总闸。每个并发 = 一个真实的模型 CLI 进程,调大会成倍加快额度消耗,网络代理高并发下也更易断连,建议逐步上调。": "Limite de tickets que o mesmo Agent fan-out (postos que processam um ticket por cena/grupo, como ativos de cena, geração de vídeo, revisão e pontuação de aceitação) pode executar simultaneamente; padrão 5, nunca acima da «Cota de concorrência entre Agents» acima. Agents criativos sempre rodam em série para proteger a continuidade da sessão e não são afetados; todas as execuções ainda passam pelo portão de concorrência entre Agents. Cada concorrência = um processo CLI real do modelo — aumentar o valor acelera proporcionalmente o consumo de cota e favorece quedas de proxy em alta concorrência; aumente gradualmente.",
"运行超时(分钟)": "Tempo limite de execução (min)",
"无输出超时(分钟)": "Tempo limite sem saída (min)",
"运行超时:单个工单从启动算起的墙钟上限,默认 120 分钟(总制片要等整条流水线,自动放宽 4 倍),到点连同派生子进程一起终止并记为出错,是回收挂死进程的最后防线。无输出超时:引擎连续多长时间没有任何事件输出即判定挂死并终止,默认 30 分钟,填 0 关闭;比墙钟更早识别 API 长连接不返回、代理断流等假死,又不会误伤跑得慢但在正常干活的长批量任务(总制片大部分时间静默等子任务,不受此项约束)。注意单次工具调用期间引擎不会有事件输出,该值须大于工单里最长的一次工具调用。均为全局设置,保存后对后续启动的工单生效。": "Tempo limite de execução: teto de relógio de parede de um ticket desde o início, padrão 120 minutos (o Produtor espera todo o pipeline e recebe automaticamente 4×); ao atingir, a execução e seus processos filhos são encerrados e marcados como erro — a última linha de defesa para recuperar processos travados. Tempo limite sem saída: por quanto tempo o motor pode ficar sem emitir nenhum evento antes de ser considerado travado e encerrado, padrão 30 minutos, 0 desativa; detecta travamentos (conexões API longas que nunca retornam, quedas de proxy) muito antes do relógio de parede sem prejudicar lotes longos lentos mas saudáveis (o Produtor passa a maior parte do tempo esperando subtarefas em silêncio e está isento). Atenção: durante uma chamada de ferramenta o motor não emite eventos, então este valor deve superar a chamada mais longa do ticket. Ambas são configurações globais e valem para execuções iniciadas após salvar.",
"运行超时需为 {min}-{max} 的整数(分钟)": "O tempo limite de execução deve ser um inteiro entre {min} e {max} (minutos)",
"无输出超时需为 0-{max} 的整数(分钟,0=关闭)": "O tempo limite sem saída deve ser um inteiro entre 0 e {max} (minutos, 0 = desativado)",
"并发额度需为 1-{max} 的整数": "A cota de concorrência deve ser um inteiro entre 1 e {max}",
