"闲置时间:每隔该时长巡检一次,流水线空闲(无任务在跑、无待确认项)才发送状态检查消息,默认 5 分钟。阈值:总制片生效引擎(claude/codex)的 5 小时窗口会话用量达到该值时,本轮不发送;用量读取不到时放行。均为全局设置,对所有项目生效(开关在运行面板 🤖 按钮,按项目独立)": "Tempo ocioso: inspeciona a cada intervalo e só envia a mensagem de verificação de status se o pipeline estiver ocioso (nenhuma tarefa rodando, nada a confirmar), padrão 5 minutos. Limite: se o uso da sessão na janela de 5 horas da engine ativa do Producer (claude/codex) atingir esse valor, não envia nesta rodada; se o uso não puder ser lido, libera. Ambos são configurações globais, valendo para todos os projetos (o interruptor fica no botão 🤖 do painel de execução, independente por projeto)",
