"(两平台账号与 Key 不互通,「接口区域」须与 Key 来源一致);克隆音色需先在平台创建;Agent 可用 --voice 按角色覆盖(传 voice_id)": " (contas e chaves não são intercambiáveis entre as duas plataformas; a “Região da API” deve corresponder à origem da chave); vozes clonadas devem ser criadas primeiro na plataforma; agentes podem sobrescrever por personagem com --voice (passando um voice_id)",
