"MiniMax 视频生成 API(MiniMax-H3,音画同生,支持首尾帧/多参考图/参考音视频);分辨率仅 768P/2K 两档:「输出设置」的 360p/480p/720p 自动映射 768P,1080p/4k 映射 2K;时长 4-15 整数秒;Key 在": "API de geração de vídeo da MiniMax (MiniMax-H3; áudio e vídeo cogerados; primeiro/último quadro, várias imagens de referência, áudio/vídeo de referência); apenas dois níveis de resolução, 768P/2K: 360p/480p/720p das configurações de saída mapeiam para 768P, 1080p/4k para 2K; duração de 4–15 segundos inteiros; a Key é criada em",
