"Agent 运行中确认问题属于系统代码缺陷、或需要系统新增功能时,自动整理成 issue 列在下方,点「提交」即打开预填好的 GitHub 页面由你确认提交。": "Quando um agente confirma durante uma execução que um problema é um defeito do código do aplicativo, ou que o aplicativo precisa de uma nova função, ele o redige automaticamente como issue e o lista abaixo; \"Enviar\" abre uma página do GitHub pré-preenchida para você confirmar.",
