"点击「启用」后,可在下方管理已入库的素材;人物预览页每张形象图会出现「入库」按钮,分镜重出时已入库(Active)的参考图自动以资产 URI(asset://素材ID)提交。": "Após clicar em Ativar, gerencie os ativos registrados abaixo; cada imagem na prévia de personagens ganha um botão Registrar e, ao regenerar um grupo, as referências registradas (Active) são enviadas automaticamente como URI de ativo (asset://ID).",
"注意:上传入库为异步审核(Processing → Active/Failed),仅 Active 状态的素材可用于视频生成;素材按方舟「项目」隔离,下方 ProjectName 须与「生成模型」页视频生成所用方舟 API Key 所属项目一致(默认 default)。": "Nota: o registro passa por revisão assíncrona (Processing → Active/Failed); apenas ativos Active podem ser usados na geração de vídeo. Os ativos são isolados por projeto do Ark — o ProjectName abaixo deve corresponder ao projeto da API Key do Ark usada na página Modelos de geração (padrão: default).",
