"Wan 3.0(Fal 托管;文生/首尾帧/多模态参考,2-30 秒,参考 10 图/5 视频/5 音频(视频、音频各合计 ≤15s),480p/720p/1080p)": "Wan 3.0 (hospedado na Fal; texto / primeiro-último quadro / referências multimodais, 2–30 s, referências 10 imagens/5 vídeos/5 áudios (vídeos e áudios ≤15 s no total cada), 480p/720p/1080p)",
"MiniMax H3(Fal 托管;首尾帧/多模态参考,480P/768P/2K/4K,参考合计 ≤12 件)": "MiniMax H3 (hospedado na Fal; primeiro/último quadro ou referências multimodais, 480P/768P/2K/4K, ≤12 arquivos de referência no total)",
"Seedream 5.0 Lite(Fal 托管;文/图生图/多参考图 ≤10,出图 2K–4K)": "Seedream 5.0 Lite (hospedado na Fal; texto/imagem para imagem, até 10 imagens de referência, saída 2K–4K)",
"Seedream 4.5(Fal 托管;文/图生图/多图融合,参考图 ≤10)": "Seedream 4.5 (hospedado na Fal; texto/imagem para imagem, fusão multi-imagem, até 10 imagens de referência)",
