"Nano Banana 2(Fal 托管;Google 快速版生成/编辑,多参考图)": "Nano Banana 2 (hospedado na Fal; modelo rápido do Google para geração/edição, várias referências)",
"GPT Image 2.5 Flare(Fal 托管;OpenAI 通用版,参考图 ≤16,无 seed)": "GPT Image 2.5 Flare (hospedado na Fal; OpenAI de uso geral, até 16 imagens de referência, sem seed)",
