"Qwen Image 3(Fal 托管;中英提示词,参考图 ≤3,支持负面提示词)": "Qwen Image 3 (hospedado na Fal; prompts em chinês/inglês, até 3 imagens de referência, suporta prompt negativo)",
"HunyuanImage 3.0(Fal 托管;仅文生图,支持负面提示词)": "HunyuanImage 3.0 (hospedado na Fal; apenas texto para imagem, suporta prompt negativo)",
"Fal 图像生成 API(queue.fal.run 异步队列,托管 Seedream、Nano Banana、GPT Image、FLUX.2、Qwen Image 等端点);模型 ID 填家族前缀,无参考图走文生图端点、有参考图自动切 edit 端点,「自定义…」也可填完整端点 ID;尺寸/参考图上限/seed 按模型映射;Key 与视频段 Fal 共用(任一处填写即可),在": "API de geração de imagens da Fal (fila assíncrona queue.fal.run que hospeda Seedream, Nano Banana, GPT Image, FLUX.2, Qwen Image e outros); o ID do modelo é o prefixo da família: sem referências usa o endpoint texto para imagem e com referências muda automaticamente para o endpoint de edição; «Personalizado…» também aceita um ID de endpoint completo; tamanho / limite de referências / seed são mapeados por modelo; a chave é compartilhada com a aba Vídeo → Fal (basta preencher uma) e é criada em",
"MiniMax H3 Max(Fal 托管;H3 后训练版,提示遵循更强)": "MiniMax H3 Max (hospedado na Fal; H3 pós-treinado, maior aderência ao prompt)",
"MiniMax H3 Max Turbo(Fal 托管;速度优先版,仅文生/首尾帧,480P/768P,不支持参考素材)": "MiniMax H3 Max Turbo (hospedado na Fal; variante rápida, apenas texto/primeiro-último quadro, 480P/768P, sem material de referência)",
"Kling 3.0 Pro(Fal 托管;首尾帧,3-15 秒,原生音频,不支持参考素材)": "Kling 3.0 Pro (hospedado na Fal; primeiro/último quadro, 3–15 s, áudio nativo, sem material de referência)",
"Kling 3.0 Standard(Fal 托管;首尾帧,3-15 秒,原生音频,不支持参考素材)": "Kling 3.0 Standard (hospedado na Fal; primeiro/último quadro, 3–15 s, áudio nativo, sem material de referência)",
"Fal 视频生成 API(queue.fal.run 异步队列,托管 Seedance 2.0/2.5、MiniMax H3、Kling 3.0、Wan 3.0 等端点);模型 ID 填家族前缀,按输入自动补 text-to-video / image-to-video / reference-to-video 任务段,「自定义…」也可填完整端点 ID;分辨率/时长/参考素材上限随所选模型(与官方渠道同口径);Key 在": "API de geração de vídeo da Fal (fila assíncrona queue.fal.run que hospeda Seedance 2.0/2.5, MiniMax H3, Kling 3.0, Wan 3.0 e outros); o ID do modelo é o prefixo da família e o segmento de tarefa text-to-video / image-to-video / reference-to-video é adicionado automaticamente conforme as entradas, ou escolha “Personalizado…” para informar um ID de endpoint completo; os limites de resolução/duração/referências seguem o modelo escolhido (mesmas regras dos canais oficiais); crie a Key no",
"fal.ai 控制台「API Keys」": "painel fal.ai “API Keys”",
"直播": "Ao vivo",
"直播:参考图 + 提示词交给 Fal 渠道视频模型循环生成 480p 短段,每段带上一段尾帧续接,页面把新段接在已播内容之后连续播放": "Ao vivo: imagens de referência + prompt vão para um modelo de vídeo da Fal que gera clipes 480p continuamente, cada um continuando do último quadro do anterior; a página anexa os novos clipes após o que já foi reproduzido para reprodução contínua",
"直播 — Agentics:VideoAgents": "Ao vivo — Agentics:VideoAgents",
"📡 直播": "📡 Ao vivo",
"参考图 + 提示词 → Fal 视频模型循环生成 480p 短段 → 尾帧续接 → 连续播放": "Referências + prompt → modelo de vídeo Fal gera clipes 480p em loop → continuação pelo último quadro → reprodução contínua",
"🗑 清理历史片段": "🗑 Limpar clipes antigos",
"删除所有已停止会话的片段视频与尾帧,释放磁盘": "Apaga os clipes e últimos quadros de todas as sessões paradas para liberar disco",
