"🖼 参考图": "🖼 Imagens de referência",
"{n}/{max} 张": "{n}/{max}",
"＋ 添加参考图(最多 8 张,PNG/JPG/WebP,可多选或拖入)": "＋ Adicionar imagens de referência (máx. 8, PNG/JPG/WebP; seleção múltipla ou arrastar)",
"人物/场景/风格锚图;每一轮都会连同上一段的尾帧一起作为参考提交,保持人物一致。启动后冻结,停止后可改。": "Imagens âncora de personagens/cena/estilo; a cada rodada são enviadas como referência junto com o último quadro do clipe anterior para manter a consistência. Congeladas após iniciar; editáveis após parar.",
"✍️ 提示词": "✍️ Prompt",
"📄 提示词": "📄 Prompt",
"画面主体、动作、氛围;不要写秒数与分辨率": "Sujeito, ação, clima; sem segundos nem resolução",
"例如:一位年轻主播坐在暖光直播间里,面对镜头微笑聊天,偶尔喝一口咖啡,背景霓虹灯牌缓慢闪烁": "ex.: Um jovem streamer sentado num estúdio de luz quente, sorrindo e conversando com a câmera, bebendo café de vez em quando, um letreiro neon piscando lentamente ao fundo",
"✏️ 更新提示词(下一段生效)": "✏️ Atualizar prompt (vale para o próximo clipe)",
