"衔接模式": "Continuidade",
"参考图 + 尾帧一起作参考(默认)": "Referências + último quadro como referências (padrão)",
"尾帧作首帧(不带参考图,衔接更平滑但人物易漂移)": "Último quadro como primeiro (sem referências; emendas mais suaves mas os personagens derivam)",
"不衔接(文生视频:每段仅按提示词独立生成,不带参考图与尾帧)": "Sem continuidade (texto para vídeo: cada clipe é gerado só a partir do prompt, sem referências nem último quadro)",
"不衔接:每段仅按提示词文生视频,参考图与尾帧都不提交,段与段之间画面不连续": "Sem continuidade: cada clipe é texto para vídeo só a partir do prompt; nem referências nem o último quadro são enviados, os clipes não se emendam visualmente",
"导演模式(MiniMax H3 Max Director:实时连续生成,WebRTC 直推,提示词随时改)": "Modo diretor (MiniMax H3 Max Director: geração contínua em tempo real, envio WebRTC, prompt editável a qualquer momento)",
"记忆段数": "Memória (segmentos)",
"导演模式:保留最近多少段提示词作为上下文(1–50,默认 12)": "Modo diretor: quantos prompts de segmentos recentes manter como contexto (1–50, padrão 12)",
"MiniMax H3 Max Director(导演模式专用,实时 WebRTC)": "MiniMax H3 Max Director (só modo diretor, WebRTC em tempo real)",
"导演模式按秒计费(最少 60 秒),单会话默认最长 2 分钟(更长需向 fal 申请);关闭页面即结束": "O modo diretor é cobrado por segundo (mínimo 60 s); cada sessão dura no máximo 2 min por padrão (mais exige aprovação da fal); fechar a página encerra",
"导演模式:fal 侧按约 10 秒一块连续生成,单段时长/待播上限/最多段数不适用": "Modo diretor: a fal gera continuamente em blocos de ~10 s; duração do clipe / limite não reproduzido / máx. de clipes não se aplicam",
"导演模式:MiniMax H3 Max Director 实时连续生成,视频经 WebRTC 直推本页,自带前文记忆不需尾帧衔接;参考图只取第 1 张作首帧;分辨率 480p/768p": "Modo diretor: o MiniMax H3 Max Director gera continuamente em tempo real, o vídeo chega a esta página por WebRTC e a memória interna dispensa a continuação por último quadro; só a referência nº 1 é usada como primeiro quadro; resolução 480p/768p",
