"⏭ 最新": "⏭ Mais recente",
"播放策略:按顺序播放已生成的片段;新片段还没到时重播最新一段,到了就在当前段结束后接上,不会打断正在播的画面。生成通常慢于播放,所以\"回放\"是常态——把单段时长调长可以减少重播占比。待播片段达到上限(默认 3 段,高级选项可调)时暂停生成,播掉一段再继续。停止后循环回放全部片段。": "Reprodução: os clipes gerados tocam em ordem; enquanto o próximo não chega, o mais recente repete, e o novo é anexado após o atual terminar sem interrompê-lo. Gerar costuma ser mais lento que reproduzir, então repetir é normal — clipes mais longos reduzem a proporção de repetição. Ao atingir o limite de clipes em espera (3 por padrão, ajustável em Opções avançadas) a geração pausa e retoma ao reproduzir um. Após parar, todos os clipes ficam em loop.",
