"语音输入": "Entrada por voz",
"语音输入:开启后控制台与预览页「修改」浮窗的输入框出现麦克风按钮,录音由本机 faster-whisper 转成文字,音频不出本机": "Entrada por voz: quando ativada, um botão de microfone aparece na caixa de entrada do console e na janela «Revisar» das páginas de pré-visualização; as gravações são transcritas localmente pelo faster-whisper e nunca saem deste computador",
"🎤 语音输入": "🎤 Entrada por voz",
"启用语音输入": "Ativar entrada por voz",
"开启后控制台输入框与预览页「修改」浮窗的右侧出现麦克风按钮:点一下开始录音、再点一下结束,录音由本机 faster-whisper 模型转成文字插到光标处(最长 60 秒,音频不出本机,不需要任何 API Key)。识别语言跟随界面语言。模型首次使用需先下载,越大的模型越准但越慢:small 起步够用,Apple 芯片可选 medium 或 large-v3-turbo。": "Quando ativada, um botão de microfone aparece à direita da caixa de entrada do console e da janela «Revisar» das páginas de pré-visualização: um clique inicia a gravação, outro a encerra; a gravação é transcrita pelo modelo local faster-whisper e inserida no cursor (máx. 60 s, o áudio não sai deste computador, sem chave de API). O idioma de reconhecimento segue o idioma da interface. O modelo precisa ser baixado antes do primeiro uso; quanto maior, mais preciso porém mais lento: small basta para começar; em chips Apple, medium ou large-v3-turbo.",
