"把时间段按倍率放慢(1s ×2 = 2s):RIFE 类工作流补帧后由宿主变速拼接,成片按拉长量变长,外挂声轨与字幕按 timemap 自动平移;声音 stretch = 保音高拉伸(段内有台词时改 sustain / fade / mute)": "Desacelera o trecho marcado pelo fator (1 s ×2 = 2 s): um fluxo tipo RIFE interpola quadros e o host muda a velocidade e emenda. O episódio cresce o quanto foi esticado; áudio externo e legendas deslocam pelo mesmo mapa de tempo. Som stretch = esticar mantendo o tom (com fala no trecho, troque para sustain / fade / mute)",
