"用本机人声分离模型把对白 / 人声从原生声轨里去掉,保留音效、环境声和配乐;画面不重编码。人声保留 -60 = 完全去掉,调高 = 只压低。首次使用自动下载模型(约 64 MB);提交后要重跑混音才进成片": "Usa um modelo local de separação de voz para remover diálogo / vozes da trilha de áudio original, mantendo efeitos, ambiente e música; a imagem não é recodificada. Voz mantida -60 = removida por completo, mais alto = apenas atenuada. O modelo (cerca de 64 MB) é baixado no primeiro uso; depois de enviar, é preciso refazer a mixagem para a mudança chegar ao corte final",
"只留人声:用本机人声分离模型把音效、环境声和配乐从原生声轨里去掉;画面不重编码。环境声保留 -60 = 完全去掉,调高 = 只压低。首次使用自动下载模型(约 64 MB);提交后要重跑混音才进成片": "Só vozes: usa um modelo local de separação de voz para remover efeitos, ambiente e música da trilha de áudio original; a imagem não é recodificada. Ambiente mantido -60 = removido por completo, mais alto = apenas atenuado. O modelo (cerca de 64 MB) é baixado no primeiro uso; depois de enviar, é preciso refazer a mixagem para a mudança chegar ao corte final",
