"插黑 / 定格": "Preto / congelado",
"把选中的时间段直接删掉,剩下的内容按原顺序拼成本组新版本(时长变短,出成片时外挂声轨/字幕按时间映射表自动同步)": "Remove os trechos marcados e junta o resto em ordem como nova versão deste grupo (a duração encurta; ao finalizar, o áudio externo e as legendas são ressincronizados pelo mapa de tempo)",
"控制切换节奏:在当前时刻插入「前一帧定格 + 黑场」生成本组新版本;或放在本组开头 / 结尾的组边界,写成组间转场调整(提交即回写 shot_list,出成片时插帧)。成片按插入量变长,外挂声轨与字幕按同一张时间映射表自动平移;黑场声音可延续前段、淡出或静音": "Controle de ritmo: insira \"congelamento do quadro anterior + preto\" na posição atual para criar uma nova versão, ou coloque na fronteira do início / fim deste grupo como ajuste de transição entre grupos (enviar grava em shot_list; os quadros são inseridos na finalização). O episódio cresce o quanto foi inserido; áudio externo e legendas deslocam pelo mesmo mapa de tempo; o som sob o preto pode sustentar, esvaecer ou silenciar",
"分镜剪辑,四个模块:① 删段——选中的时间段直接删除,剩余拼成新版本;② 换段——切掉的时间段用本组另一版本同段替代;③ 插黑 / 定格——在当前时刻或组边界插入定格帧 + 黑场控制切换节奏;④ 派单剪辑师——输入指令发给剪辑师工位,产物登记为新版本": "Edição de planos, quatro módulos: ① Excluir — remove os trechos marcados, o resto vira nova versão; ② Substituir — troca os trechos cortados pelos mesmos trechos de outra versão; ③ Preto / congelado — insere congelamento + preto na posição atual ou na fronteira do grupo para controlar o ritmo; ④ Enviar ao editor — envia uma instrução ao agente editor; o resultado é registrado como nova versão",
