"按集过滤:只显示该集出现的资产": "Filtrar por episódio: mostrar apenas os recursos que aparecem nele",
"Agent 高级设置:扇出型 Agent 并发额度、运行/无输出超时、跨轮对话记忆额度、自动重跑次数上限、重跑等待确认时间、思考深度、白模自检、Debug 模式": "Configurações avançadas de agentes: concorrência de agentes fan-out, tempos limite de execução / sem saída, cota de memória de conversa entre turnos, teto de repetições automáticas, tempo de espera da confirmação de repetição, profundidade de raciocínio, autoverificação de whitebox, modo Debug",
"白模自检": "Autoverificação de whitebox",
"显示 SOUL.md 等开发者入口": "Mostrar entradas de desenvolvedor como SOUL.md",
"白模调度编译后出静帧自检取景": "Renderizar quadros estáticos após compilar o whitebox para autoverificar o enquadramento",
"默认勾选:白模调度 Agent 每次新建或修改分镜白模、编译通过后,用宿主命令 render_whitebox.py --stills 对本单改动过的组做无头渲染——每镜取首/中/尾等时刻的摄影机视角加一张空间视角,拼成每组一张联系表(项目 directing 下该集的 whitebox/stills 目录),Agent 读图核对主体是否在画内、有无被墙或道具遮挡、正面/背影与调度是否一致、景别是否相符,有问题先自行修正或开待决项,再交你在预览页审看签字。渲染全在本机完成,不调用任何生成模型、不产生费用,也不导出 camera.mp4(导出仍须 H3W 签字);每组约多花十几秒与一次读图的 token。取消勾选则只做数值自检与宿主机检,不出静帧。全局设置,通过运行提示词注入白模调度 Agent,保存后对后续启动的工单生效。": "Marcado por padrão: sempre que o agente de encenação whitebox cria ou altera um whitebox de storyboard e a compilação passa, ele executa o comando do host render_whitebox.py --stills nos grupos alterados nessa ordem de trabalho. A renderização é sem interface: para cada plano, vistas da câmera no início / meio / fim (e outros momentos-chave) mais uma vista espacial, reunidas em uma folha de contato por grupo (na pasta whitebox/stills do episódio dentro de directing do projeto). O agente lê a folha para verificar se o sujeito está em quadro, se nada é encoberto por paredes ou objetos, se frente / costas correspondem à encenação e se o tamanho do plano é adequado; corrige os problemas por conta própria ou abre um item pendente antes de passar para você revisar e assinar na página de pré-visualização. A renderização é totalmente local: nenhum modelo generativo é chamado, não há custo e camera.mp4 não é exportado (a exportação ainda exige a assinatura H3W); cada grupo custa cerca de dez segundos extras e os tokens de uma leitura de imagem. Desmarcado: apenas autoverificações numéricas e verificações do host, sem quadros estáticos. Configuração global, injetada no agente de encenação whitebox pelo prompt de execução; vale para ordens iniciadas após salvar.",
"本组尚未白模调度，当前没有可审看的白模。": "Este grupo ainda não passou pela encenação whitebox; não há whitebox para revisar.",
"白模调度 Agent 完成本集工单后这里会显示正式白模；在此之前无需对白模提修改意见。": "O whitebox oficial aparecerá aqui quando o agente de encenação whitebox concluir a ordem deste episódio; até lá não é preciso enviar correções do whitebox.",
"系统按分镜与动线自动推断的粗略白模，机位、走位、朝向多为估计值，不是白模调度的交付物": "Whitebox aproximado inferido automaticamente a partir do storyboard e do blocking; posições de câmera, deslocamentos e orientações são em sua maioria estimativas, não uma entrega da encenação whitebox",
"查看自动推断草稿（仅供参考，不接受修改）": "Ver rascunho inferido automaticamente (apenas referência, não aceita alterações)",
