"勾选:在手绘稿基础上由 AI 按对应风格重绘;不勾选:直接使用手绘原图": "Marcado: a IA redesenha o seu esboço no estilo correspondente; desmarcado: o desenho original é usado como está",
"画一张分镜草图,提交后 AI 按分镜草图风格重绘,作为该镜草图": "Desenhe um esboço de storyboard; após enviar, a IA o redesenha no estilo de esboço de storyboard e ele se torna o esboço deste plano",
"可选:补充说明(构图/人物/动作,AI 重绘时参考)": "Opcional: notas adicionais (composição / personagens / ação) para o redesenho por IA",
"手绘原图将直接加入本组参考图(不经 AI 加工)": "O desenho original será adicionado diretamente às referências deste grupo (sem processamento por IA)",
"可选:这张图表达什么": "Opcional: o que este desenho expressa",
"✅ 已提交 {f},AI 正在按分镜草图风格重绘,请回故事板页查看进度": "✅ {f} enviado; a IA está redesenhando no estilo de esboço de storyboard — acompanhe o progresso na página de storyboard",
"✅ 已提交 {f},手绘原图已直接加入本组参考图,请回桌面端查看": "✅ {f} enviado; o desenho original foi adicionado às referências deste grupo — veja no computador",
"手机扫码手绘构图线稿;勾选「AI 加工」(默认)结合已有参考图按项目风格生成最终参考图,不勾选则手绘原图直接加入本组": "Escaneie com o celular e desenhe um esboço de composição; com «Retoque por IA» marcado (padrão), uma imagem de referência final é gerada a partir do esboço, das referências existentes e do estilo do projeto; desmarcado, o desenho original é adicionado diretamente ao grupo",
"手机扫码打开画布(同一局域网);画构图线稿并配文字说明,提交后结合本组已有参考图与项目风格生成最终参考图,自动加入本组;画布页取消勾选「AI 加工」则手绘原图直接加入本组": "Escaneie o QR code com o celular para abrir a tela de desenho (mesma LAN); desenhe um esboço de composição e adicione uma nota — após enviar, uma imagem de referência final é gerada a partir do esboço, das referências existentes do grupo e do estilo do projeto, e adicionada automaticamente; desmarque «Retoque por IA» na página de desenho para adicionar diretamente o desenho original",
"✅ 手绘原图已加入本组参考图": "✅ Desenho original adicionado às referências deste grupo",
"手机扫码打开画布(同一局域网);画好提交后由 AI 按分镜草图风格重绘作为该分镜的草图;画布页取消勾选「AI 加工」则手绘原图直接作为草图": "Escaneie o QR code com o celular (mesma LAN) para abrir a tela de desenho; após enviar, a IA o redesenha no estilo de esboço de storyboard como esboço deste plano; desmarque «Retoque por IA» na página de desenho para usar diretamente o desenho original",
"手机扫码画一张草图;默认由 AI 按分镜草图风格重绘,画布页取消勾选「AI 加工」则原图直接作为这一镜的草图": "Escaneie com o celular e desenhe um esboço; por padrão a IA o redesenha no estilo de esboço de storyboard — desmarque «Retoque por IA» na página de desenho para usar o original como esboço deste plano",
"手绘稿 AI 加工": "Desenho à mão retocado por IA",
"✅ 已收到手绘稿,AI 正在按分镜草图风格重绘…": "✅ Desenho recebido; a IA está redesenhando no estilo de esboço de storyboard…",
"MiniMax H3 Max Lip Sync(Fal 托管;对口型:1 张人物图 + 1 段 5–14.8 秒音频,无提示词,成片时长随音频,480P/768P/1080P/2K)": "MiniMax H3 Max Lip Sync (hospedado na Fal; sincronia labial: 1 imagem do personagem + 1 áudio de 5–14,8 s, sem prompt, duração segue o áudio, 480P/768P/1080P/2K)",
"MiniMax H3 Max Lip Sync:每段都用第 1 张参考图作人物图(画面不漂,但段与段之间会跳);画幅随图片": "MiniMax H3 Max Lip Sync: cada clipe usa a referência n.º 1 como imagem do personagem (sem deriva, mas com saltos entre clipes); a proporção segue a imagem",
"MiniMax H3 Max Lip Sync:首轮用第 1 张参考图作人物图,之后每轮用上一段尾帧(衔接模式选「不衔接」则每段都用第 1 张参考图);画幅随图片": "MiniMax H3 Max Lip Sync: a 1ª rodada usa a referência n.º 1 como imagem do personagem e as seguintes o último quadro do clipe anterior (com “Sem ligação”, sempre a referência n.º 1); a proporção segue a imagem",
"对口型模型需要至少 1 张参考图(第 1 张作为人物图)": "O modelo de sincronia labial precisa de pelo menos 1 imagem de referência (a n.º 1 é a imagem do personagem)",
"💬 台词": "💬 Fala",
"人物要说的话;按句分段,逐段语音合成后驱动口型": "O que o personagem diz; dividido por frases, cada trecho é sintetizado em voz e depois move os lábios",
"例如:大家好,欢迎来到我的直播间!今天想和大家聊一聊最近在看的一本书。": "ex.: Olá, pessoal, bem-vindos à minha live! Hoje quero falar sobre um livro que estou lendo.",
"语音用「生成模型」页当前的 TTS 配置与默认音色合成({tts})。台词念完不会停播,会等你更新台词:在原文后面追加的部分接着念,整段改写则从头念新台词。": "A voz é sintetizada com a configuração de TTS atual e a voz padrão da página “Modelos de geração” ({tts}). A transmissão não para quando a fala termina, ela aguarda uma atualização: o texto acrescentado ao final é dito em seguida; uma fala reescrita recomeça do início.",
"对口型:台词按句打包成每段约该秒数({lo}–{hi} 秒)的小段;每段成片时长 = 该段语音时长(不足 5 秒补静音)": "Sincronia labial: a fala é agrupada por frases em trechos de cerca desta duração ({lo}–{hi} s); cada clipe dura o mesmo que sua voz (preenchido com silêncio abaixo de 5 s)",
"✏️ 更新台词": "✏️ Atualizar fala",
"台词已更新": "Fala atualizada",
"对口型模型需要填写台词(人物要说的话)": "O modelo de sincronia labial precisa de uma fala (o que o personagem diz)",
"点击打开 360° 预览": "Clique para abrir a pré-visualização 360°",
"360° 预览": "Pré-visualização 360°",
"平面原图": "Imagem plana",
"拖动环视 360°,滚轮缩放,双击复位,Esc 关闭": "Arraste para olhar em 360°, role para dar zoom, clique duplo para redefinir, Esc para fechar",
