"分镜草案没写 narration_ref、镜头表也还没定挂点,宿主按旁白稿锚点引文推定到镜;签字前请核对": "O rascunho do storyboard não traz narration_ref e a lista de planos ainda não tem âncoras; o host inferiu o plano pela citação de âncora do rascunho de narração. Confira antes de assinar.",
"旁白(正文·估时;灰标 = 宿主推定的挂点)": "Narração (texto · duração estimada; etiqueta cinza = âncora inferida pelo host)",
"分镜剪辑": "Edição de planos",
"待确认": "A confirmar",
"{g} 有 {n} 个新版本待确认": "{g} tem {n} nova(s) versão(ões) a confirmar",
"对比 v{v}": "Comparar v{v}",
"把当前指针挪到 v{v}(出成片用它)": "Mover o ponteiro atual para v{v} (usada no corte final)",
"分镜剪辑,三个模块:① 删段——选中的时间段直接删除,剩余拼成新版本;② 换段——切掉的时间段用本组另一版本同段替代;③ 派单剪辑师——输入指令发给剪辑师工位,产物登记为新版本": "Edição de planos, três módulos: ① Excluir — remove os trechos marcados e o resto vira uma nova versão; ② Substituir — troca os trechos cortados pelos mesmos trechos de outra versão deste grupo; ③ Enviar ao editor — digite uma instrução para a estação do editor; o resultado é registrado como nova versão",
"删段": "Excluir",
"换段": "Substituir",
"派单剪辑师": "Enviar ao editor",
"把选中的时间段直接删掉,剩下的内容按原顺序拼成本组新版本(时长变短,出成片前需同步时间线)": "Remove de vez os trechos marcados e junta o restante, na ordem, numa nova versão deste grupo (a duração diminui; sincronize a linha do tempo antes do corte final)",
"导入本组另一版本作替换源,A 上标出的时间段换成替换源同一时间段的画面,其余保留,拼成新版本(时长不变)": "Importa outra versão deste grupo como fonte de substituição: os trechos marcados em A são trocados pelos mesmos trechos dessa fonte, o resto é mantido e uma nova versão é montada (duração inalterada)",
"用一句话把剪辑要求发给剪辑师工位(10-editing/edit);可附上标好的时间段供指令引用,剪辑师产物会登记为本组新版本": "Envie numa frase o pedido de edição à estação do editor (10-editing/edit); é possível anexar os trechos marcados para a instrução citá-los, e o resultado do editor é registrado como nova versão deste grupo",
"删 {n} 段 · -{s}s → 剩 {r}s": "Excluir {n} trecho(s) · -{s}s → restam {r}s",
"要删除的时间段(A 的时间线)": "Trechos a excluir (na linha do tempo de A)",
"时间段(可选,随指令一起发给剪辑师供引用)": "Trechos (opcional; enviados junto com a instrução para o editor citar)",
"没有时间段也能派单;要让剪辑师精确到秒,先在走带条上「标记时间段」": "Também dá para despachar sem trechos; para dar segundos exatos ao editor, use antes «Marcar trecho» na barra de transporte",
"还没有要删的段:播放 A 找到要删掉的部分,点「标记时间段」设起点、再点一次设终点,即加入列表;可标多段": "Ainda não há trechos a excluir: reproduza A para achar a parte a remover, clique em «Marcar trecho» para o ponto de entrada e clique de novo para o de saída; dá para marcar vários",
"给剪辑师的指令,例如:第 1 段太拖,砍到 1.5 秒;结尾定格 0.5 秒后再切": "Instrução para o editor, por exemplo: o trecho 1 está arrastado, corte para 1,5 s; congele o último quadro por 0,5 s antes do corte",
"本组近期工单": "Ordens recentes deste grupo",
"{n} 段": "{n} trecho(s)",
"删除并生成新版本": "Excluir e criar nova versão",
"发送给剪辑师": "Enviar ao editor",
