"把走带条上「标记时间段」得到的段加入列表;剪辑面板打开时标记完成会自动加入": "Adiciona à lista o trecho obtido com «Marcar trecho» na barra de transporte; com o painel de edição aberto, a marcação concluída entra automaticamente",
"加入标记段": "Adicionar trecho marcado",
