// 生成模型设置·超分板块 + 成片发布页组 clip 方法标签(2026-09-23,models.html / preview_videos.html)
"图像 / 视频 / 数字人 / 超分 / 音乐 / TTS旁白 / 世界模型 生成渠道与模型": "Provedores e modelos: imagem / vídeo / humano digital / upscale / música / narração TTS / modelo de mundo",
"🔍 超分": "🔍 Upscale",
"生效渠道=当前选中的标签页(✅),不再跟随视频渠道,保存后生效": "Provedor ativo = aba selecionada (✅), não segue mais o provedor de vídeo; vale após salvar",
"缩放算法": "Filtro de escala",
"lanczos(默认,较锐利)": "lanczos (padrão, mais nítido)",
"bicubic(平滑)": "bicubic (suave)",
"bilinear(最软)": "bilinear (mais suave)",
"0–51,越小画质越高体积越大;18 ≈ 视觉无损": "0–51; menor = mais qualidade e mais tamanho; 18 ≈ sem perda visual",
"编码预设": "Preset do codificador",
"slow(默认)": "slow (padrão)",
"内置非 AI 插值放大:ffmpeg scale 滤镜 + libx264 重编码,音轨流拷贝,fps/时长/画幅不变。不生成新细节,只是像素变多;不花生成费,适合只需过发布规格的项目。目标尺寸由「输出设置」成片分辨率 × 画幅自动换算。": "Interpolação integrada sem IA: filtro scale do ffmpeg + recodificação libx264, áudio copiado, fps/duração/proporção inalterados. Não gera detalhe novo, só mais pixels; sem custo de geração, serve para projetos que só precisam cumprir a especificação de publicação. O tamanho-alvo vem da resolução de entrega × proporção das Configurações de saída.",
"Seedance 2.5 样片(Draft)模式:选中即激活,无需另填 Key 或模型,凭证与模型沿用视频生成的火山引擎标签页。": "Modo Draft do Seedance 2.5: ativa ao selecionar esta aba; sem chave ou modelo extra, credenciais e modelo vêm da aba Volcano Engine da geração de vídeo.",
"激活条件:视频生效渠道为火山引擎(或 BytePlus,方舟同一 API)且模型为 Seedance 2.5;项目「输出设置」草稿分辨率 = 480p、成片分辨率 = 1080p(官方:样片仅 480p,出原片仅 1080p)。不满足时视频照常按普通模式生成,并在日志提示。": "Condições: o provedor de vídeo ativo é Volcano Engine (ou BytePlus, mesma API Ark) com modelo Seedance 2.5, e as Configurações de saída do projeto usam 480p de rascunho e 1080p de entrega (oficial: rascunhos só 480p, finais só 1080p). Caso contrário o vídeo é gerado normalmente e o log avisa.",
"工作方式:① 生成阶段自动带 draft=true 出 480p 样片(token 用量与普通 480p 一致),Draft 任务 ID 写进组 clip 同名 meta.json 的 draft_task 段;② 超分阶段 genmedia.py upscale 按该 ID 让方舟复用同一提示词/素材/时长/画幅/seed/音频设置生成 1080p 原片(正常推理计费),画面关键要素与过审样片一致;③ Draft 任务 ID 自创建起 7 天有效,过期只能重出样片。": "Como funciona: ① a geração envia draft=true e produz um rascunho 480p (mesmo consumo de um 480p normal); o id da tarefa draft vai para o bloco draft_task do meta.json do clipe; ② no upscale, genmedia.py upscale pede ao Ark o final 1080p a partir desse id, reutilizando prompt/materiais/duração/proporção/seed/áudio (cobrança normal), então os elementos-chave batem com o rascunho aprovado; ③ o id vale 7 dias desde a criação; depois é preciso regenerar o rascunho.",
"适用条件(源 clip 必须是 MiniMax-H3 768P 直出规格):含音轨;24 fps;宽高均能被 32 整除;面积 ≤ 768×1344;107–362 帧(约 4–15 秒)。": "Condições (o clipe de origem deve ser saída nativa MiniMax-H3 768P): com faixa de áudio; 24 fps; largura e altura divisíveis por 32; área ≤ 768×1344; 107–362 quadros (cerca de 4–15 s).",
"云端超分工作流": "Workflow de upscale na nuvem",
"超分工作流 API": "API do workflow de upscale",
"创建(需 Comfy Cloud 订阅,与网页版共用月度额度,免费档无 API 权限);工作流下拉与本地一致(comfy/scale-* 模板;SeedVR2 节点 ComfyUI 官方内置,云端可用);长片 1080p 以上在云端可能显存不足,以任务结果为准": "(exige assinatura Comfy Cloud, compartilha os créditos mensais com a versão web; o plano gratuito não tem API); a lista de workflows é a mesma da local (modelos comfy/scale-*; nós SeedVR2 são nativos do ComfyUI oficial e funcionam na nuvem); clipes longos em 1080p ou mais podem estourar a VRAM na nuvem, vale o resultado da tarefa",
"获取;请先在工作区跑通 SeedVR2 类超分工作流,再把工作流 ID 或页面链接粘贴到「添加工作流」验证;无占位符的普通导出件系统会直绑唯一的源视频加载节点(LoadVideo 系)+ SeedVR2Preprocess 上游的缩放节点(目标边长/宽高)+ 采样器种子,也兼容 VIDEO/WIDTH/HEIGHT/SEED 占位符;这里的工作流收藏与视频生成板块各自独立;国内站与国际站账号与 Key 不互通": "; primeiro faça um workflow de upscale tipo SeedVR2 rodar no workspace e cole o ID ou a URL da página em “Adicionar workflow” para verificar; numa exportação comum sem marcadores o sistema vincula o único nó de carga de vídeo (família LoadVideo) + o nó de redimensionamento antes do SeedVR2Preprocess (lado / largura e altura alvo) + a seed do sampler; marcadores VIDEO/WIDTH/HEIGHT/SEED também são aceitos; os favoritos aqui são independentes do cartão de vídeo; contas e chaves .cn e .ai não são intercambiáveis",
"🧩 组 clip 与超分方法": "🧩 Clipes de grupo e método de upscale",
"{n} 组 · assets/clips/{ep}/": "{n} grupos · assets/clips/{ep}/",
