"按下方「集尾收束」": "veja “Encerramento do episódio” abaixo",
"集尾淡出时长需在 0.3–3 秒之间": "O fade de encerramento deve ter 0,3–3 s",
"集尾停留需在 0–3 秒之间": "A retenção de encerramento deve ter 0–3 s",
"切黑须停留 >0 秒(否则等于停在末帧)": "O corte para preto precisa de retenção > 0 s (senão apenas para no último quadro)",
"正片结尾的收束:最后一组尾部淡出到黑/白后停留,或直接切黑(突然黑屏,悬念感;声音默认同刻切断);外挂声轨同刻淡出/切断,片尾包装接在停留之后。出成片时由 render_transitions 落地;某一集要不同处理可在分镜预览页过场汇总条单独设。": "Como o episódio termina: o último grupo esmaece para preto/branco e mantém, ou corta direto para preto (blackout súbito para suspense; o áudio corta no mesmo instante por padrão); a trilha de áudio externa esmaece/corta no mesmo momento e os créditos seguem a retenção. Aplicado por render_transitions na renderização final; um episódio pode substituir isso na barra de resumo de transições da página de storyboard.",
"正片结尾的收束:最后一组尾部淡出/切黑后停留,外挂声轨同刻淡出或切断;片尾包装接在停留之后": "Como o episódio termina: o último grupo esmaece/corta para preto e mantém; o áudio externo esmaece ou corta no mesmo momento; os créditos seguem a retenção",
"本集集尾收束(集级覆盖,项目默认在「视频节奏」设置);改后出成片时落地,已有成片须重跑转场": "Encerramento deste episódio (substituição por episódio; o padrão do projeto está em “Ritmo do vídeo”); aplicado na renderização final, um corte existente precisa reexecutar as transições",
"渲染集尾预览小片:末组尾 2s + 收束,与成片同一滤镜链": "Renderizar a prévia do encerramento: últimos 2 s do último grupo + encerramento, mesma cadeia de filtros do corte final",
// NSFW 模式(设置→高级;index.html 弹窗 + preview_storyboard.html 组卡 🔞)
"NSFW 模式": "Modo NSFW",
"NSFW 模式:默认关;开启后可为语言/图像/视频分别指定备用模型,标记 NSFW 的工单与分镜组自动改走备用模型,主渠道内容审核拒收时自动切换重提一次": "Modo NSFW: desativado por padrão; ao ativar, é possível definir um modelo reserva separado para linguagem/imagem/vídeo; tickets e grupos marcados como NSFW passam automaticamente para os modelos reserva e, se o provedor principal rejeitar o conteúdo na moderação, ele alterna e reenvia uma vez",
"🔞 NSFW 模式": "🔞 Modo NSFW",
"启用 NSFW 模式": "Ativar o modo NSFW",
"默认关。开启后可分别指定三类「备用模型」;派单与出图/出片按三层路由决定何时改用备用模型:① 显式标记优先——工单带 nsfw: true(总制片按剧本拆解表事件 content_flags → 分镜组 nsfw 推导,或你在分镜预览组卡点 🔞 手动标记)首次派单即走备用模型;② 兜底——主渠道返回内容审核拒收时,genmedia 同一调用内改备用渠道重提一次(不计重跑次数)并把该组记为 NSFW,后续不再先撞主模型;语言模型被拒不做进程内切换,同一 task_id 重派时改用备用语言模型。本模式只决定用哪套模型,不放宽内容安全审核与平台分级。": "Desativado por padrão. Ao ativar, é possível definir um “modelo reserva” para cada um dos três tipos; o despacho e a geração de imagem/vídeo decidem quando usar o reserva em três níveis: ① marcação explícita primeiro — um ticket com nsfw: true (o Producer deriva o nsfw do grupo a partir dos content_flags dos eventos na decupagem do roteiro, ou você marca manualmente com 🔞 no cartão do grupo na prévia do storyboard) vai para o modelo reserva já no primeiro despacho; ② rede de segurança — quando o provedor principal devolve uma rejeição de moderação de conteúdo, o genmedia reenvia uma vez ao provedor reserva na mesma chamada (não conta como reexecução) e registra o grupo como NSFW para não tentar primeiro o modelo principal; um modelo de linguagem rejeitado não é trocado no processo — o modelo de linguagem reserva é usado ao redespachar o mesmo task_id. Este modo só decide qual conjunto de modelos é usado; não afrouxa a revisão de segurança de conteúdo nem a classificação das plataformas.",
"图像模型": "Modelo de imagem",
"渠道须已在「🎨 生成模型」页配好 Key(未配置的置灰);留「不设置」= 该类不切换,照常走主模型。ComfyUI 的二级选项是运行方式。备用渠道不可用时不会偷跑主模型,而是报错交你裁决。": "O provedor precisa já ter a Key configurada na página “🎨 Modelos de geração” (os não configurados ficam acinzentados); deixar “Não definido” = esse tipo não alterna e segue no modelo principal. No ComfyUI, a opção de segundo nível é o modo de execução. Se o provedor reserva estiver indisponível, o modelo principal não é executado às escondidas: um erro é reportado para você decidir.",
"审核拒收后自动切换": "Alternar automaticamente após rejeição de moderação",
"关闭后只按显式标记路由,主渠道审核拒收照常报错": "Desativado: o roteamento segue apenas marcações explícitas; uma rejeição de moderação do provedor principal gera erro como sempre",
"该运行方式未配置": "Este modo de execução não está configurado",
